# confidence=high  # note: Assumed app name matching is case-insensitive and that an app absent from the apps list (or with ins
def check_app_permissions(state, app_name):
    """Checks what permissions a specific app currently has.

    Read-only. Raises ValueError if the app is not installed on the device.
    """
    if not app_name or not isinstance(app_name, str):
        raise ValueError("app_name is required")

    target = app_name.strip().lower()

    app_record = None
    for app in _rows(state, "apps"):
        if str(app.get("app_name", "")).strip().lower() == target:
            app_record = app
            break

    if app_record is None:
        raise ValueError("App '" + app_name + "' is not installed on the device.")

    if not app_record.get("installed", False):
        raise ValueError("App '" + app_name + "' is not installed on the device.")

    granted = []
    denied = []
    for perm in _rows(state, "app_permissions"):
        if str(perm.get("app_name", "")).strip().lower() != target:
            continue
        permission_name = perm.get("permission")
        if perm.get("granted", False):
            granted.append(permission_name)
        else:
            denied.append(permission_name)

    return {
        "app_name": app_record.get("app_name"),
        "installed": app_record.get("installed", False),
        "granted_permissions": granted,
        "denied_permissions": denied,
    }

