# confidence=high  # note: Assumed airplane mode implies no signal icon and that network technology is only shown when there is
def check_status_bar(state):
    """Read-only: report the icons currently visible in the phone's status bar."""
    phone = state.get("phone", {}) or {}

    icons = []

    # Airplane mode
    if phone.get("airplane_mode"):
        icons.append("\u2708\ufe0f Airplane Mode")

    # Signal strength
    signal_map = {
        "none": "\U0001F4F5 No Signal",
        "poor": "\U0001F4F6\u00b9 Poor",
        "fair": "\U0001F4F6\u00b2 Fair",
        "good": "\U0001F4F6\u00b3 Good",
        "excellent": "\U0001F4F6\u2074 Excellent",
    }
    if phone.get("airplane_mode"):
        signal_icon = signal_map["none"]
    else:
        strength = str(phone.get("signal_strength", "none")).strip().lower()
        signal_icon = signal_map.get(strength, signal_map["none"])
    icons.append(signal_icon)

    # Network technology (only meaningful when there is signal)
    network_type = phone.get("network_type")
    if (not phone.get("airplane_mode")
            and str(phone.get("signal_strength", "none")).strip().lower() != "none"
            and network_type):
        icons.append(str(network_type))

    # Mobile data status
    if phone.get("mobile_data_enabled"):
        icons.append("\U0001F4F1 Data Enabled")
    else:
        icons.append("\U0001F4F5 Data Disabled")

    # Data saver
    if phone.get("data_saver_enabled"):
        icons.append("\U0001F53D Data Saver")

    # Wi-Fi
    if phone.get("wifi_enabled"):
        ssid = phone.get("wifi_ssid")
        if ssid:
            icons.append("\U0001F4E1 Connected to " + str(ssid))
        else:
            icons.append("\U0001F4E1 Enabled")

    # VPN
    if phone.get("vpn_active") and phone.get("vpn_connected"):
        icons.append("\U0001F512 VPN Connected")

    # Battery
    battery = phone.get("battery_level", 0)
    icons.append("\U0001F50B {}%".format(battery))

    return {
        "status_bar": "  ".join(icons),
        "icons": icons,
    }

