def check_vpn_status(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("No phone device state available")

    vpn_active = bool(phone.get("vpn_active", False))
    vpn_connected = bool(phone.get("vpn_connected", False))
    performance_level = phone.get("vpn_performance_level")

    if not vpn_active:
        summary = "VPN is OFF"
    elif vpn_connected:
        summary = "VPN is ON and connected"
    else:
        summary = "VPN is ON but not connected"

    result = {
        "vpn_active": vpn_active,
        "vpn_connected": vpn_connected,
        "summary": summary,
    }

    if vpn_active and vpn_connected:
        result["performance_level"] = performance_level

    return result

