# confidence=medium  # note: No explicit preconditions were given; I assumed VPN cannot be connected while Airplane Mode is ON (a
def connect_vpn(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("No phone found in state.")

    if phone.get("airplane_mode"):
        raise ValueError("Cannot connect VPN while Airplane Mode is ON.")

    if phone.get("vpn_active") and phone.get("vpn_connected"):
        return "VPN is already ON and connected."

    phone["vpn_active"] = True
    phone["vpn_connected"] = True

    performance = phone.get("vpn_performance_level")
    if performance:
        return "VPN is now ON and connected. Connection performance level: {}.".format(performance)
    return "VPN is now ON and connected."

# confidence=medium  # note: Assumed ownership verification (line must belong to the given customer) is the precondition; treated
def disable_roaming(state, customer_id, line_id):
    # Validate customer exists
    customer = _find(state, "customers", "customer_id", customer_id)

    # Validate line exists
    line = _find(state, "lines", "line_id", line_id)

    # Ownership check
    if line.get("customer_id") != customer.get("customer_id"):
        raise ValueError(
            "Line {} does not belong to customer {}.".format(line_id, customer_id)
        )

    if not line.get("roaming_enabled", False):
        return "Roaming is already disabled on line {}.".format(line_id)

    line["roaming_enabled"] = False
    return "Roaming has been disabled on line {}.".format(line_id)

# confidence=medium  # note: Assumed calling the tool with no active/connected VPN is a precondition failure (ValueError). Also a
def disconnect_vpn(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("Phone state is not available.")

    if not phone.get("vpn_active") and not phone.get("vpn_connected"):
        raise ValueError("There is no active VPN connection to disconnect.")

    was_poor = str(phone.get("vpn_performance_level", "")).strip().lower() == "poor"

    phone["vpn_active"] = False
    phone["vpn_connected"] = False

    # If the VPN was degrading the connection, speed recovers once it is off,
    # provided nothing else is blocking data connectivity.
    data_ok = (
        not phone.get("airplane_mode")
        and phone.get("mobile_data_enabled")
        and str(phone.get("sim_status", "")).strip().lower() == "active"
        and str(phone.get("signal_strength", "")).strip().lower() not in ("none", "")
    )
    if was_poor and data_ok:
        phone["download_speed"] = "excellent"
        phone["connection_quality"] = "excellent"

    return "VPN disconnected. Your internet traffic is no longer routed through the VPN server."

# confidence=high  # note: Assumed preconditions: the line must exist and belong to the given customer, must not be Closed, and
def enable_roaming(state, customer_id, line_id):
    customer = _find(state, "customers", "customer_id", customer_id)
    line = _find(state, "lines", "line_id", line_id)

    if line.get("customer_id") != customer_id:
        raise ValueError(
            "Line " + str(line_id) + " does not belong to customer " + str(customer_id) + "."
        )

    status = str(line.get("status", "")).strip().lower()
    if status == "closed":
        raise ValueError("Cannot enable roaming on a closed line.")

    if line.get("roaming_enabled") is True:
        raise ValueError("Roaming is already enabled on line " + str(line_id) + ".")

    line["roaming_enabled"] = True

    return (
        "Roaming has been enabled at no cost on line "
        + str(line_id)
        + " ("
        + str(line.get("phone_number"))
        + ") for customer "
        + str(customer.get("full_name", customer_id))
        + "."
    )

# confidence=high  # note: "Most recent first" is implemented as descending sort on issue_date (falling back to period_end, the
def get_bills_for_customer(state, customer_id, limit=None):
    # Verify the customer exists (raises ValueError if absent)
    _find(state, "customers", "customer_id", customer_id)

    if limit is not None:
        if isinstance(limit, bool) or not isinstance(limit, int):
            raise ValueError("limit must be an integer")
        if limit < 0:
            raise ValueError("limit must be a non-negative integer")

    bills = [b for b in _rows(state, "bills") if b.get("customer_id") == customer_id]

    def _sort_key(bill):
        return (
            str(bill.get("issue_date") or ""),
            str(bill.get("period_end") or ""),
            str(bill.get("bill_id") or ""),
        )

    bills = sorted(bills, key=_sort_key, reverse=True)

    if limit is not None:
        bills = bills[:limit]

    result = []
    for b in bills:
        result.append({
            "bill_id": b.get("bill_id"),
            "customer_id": b.get("customer_id"),
            "period_start": b.get("period_start"),
            "period_end": b.get("period_end"),
            "issue_date": b.get("issue_date"),
            "total_amount_due": b.get("total_amount_due"),
            "due_date": b.get("due_date"),
            "status": b.get("status"),
        })

    return {"customer_id": customer_id, "count": len(result), "bills": result}

