# confidence=high  # note: Assumed the tool is read-only and should verify the line belongs to the given customer. Included pla
def get_data_usage(state, customer_id, line_id):
    # Validate customer exists
    customer = _find(state, "customers", "customer_id", customer_id)

    # Validate line exists
    line = _find(state, "lines", "line_id", line_id)

    # Ensure the line belongs to the customer
    if line.get("customer_id") != customer_id:
        raise ValueError(
            "Line " + str(line_id) + " does not belong to customer " + str(customer_id)
        )

    plan_id = line.get("plan_id")
    plan = None
    if plan_id:
        for p in _rows(state, "plans"):
            if p.get("plan_id") == plan_id:
                plan = p
                break
    if plan is None:
        raise ValueError("Plan " + str(plan_id) + " not found for line " + str(line_id))

    data_usage_gb = line.get("data_usage_gb", 0)
    data_refueling_gb = line.get("data_refueling_gb", 0)
    data_limit_gb = plan.get("data_limit_gb", 0)

    return {
        "line_id": line.get("line_id"),
        "customer_id": customer_id,
        "phone_number": line.get("phone_number"),
        "status": line.get("status"),
        "plan_id": plan_id,
        "plan_name": plan.get("name"),
        "data_usage_gb": data_usage_gb,
        "data_refueling_gb": data_refueling_gb,
        "data_limit_gb": data_limit_gb,
        "total_data_available_gb": data_limit_gb + data_refueling_gb,
        "cycle_end_date": line.get("cycle_end_date"),
    }

# confidence=high  # note: Assumed the tool is a read-only lookup; enriched customer results with their payment methods, line I
def get_details_by_id(state, id):
    """Retrieve details for a Customer, Line, Device, Bill, or Plan ID."""
    if id is None or not str(id).strip():
        raise ValueError("id is required")

    target = str(id).strip()

    # Customer
    for customer in _rows(state, "customers"):
        if customer.get("customer_id") == target:
            details = dict(customer)
            details["entity_type"] = "customer"
            details["payment_methods"] = [
                dict(pm)
                for pm in _rows(state, "payment_methods")
                if pm.get("customer_id") == target
            ]
            details["line_ids"] = [
                ln.get("line_id")
                for ln in _rows(state, "lines")
                if ln.get("customer_id") == target
            ]
            details["bill_ids"] = [
                b.get("bill_id")
                for b in _rows(state, "bills")
                if b.get("customer_id") == target
            ]
            return details

    # Line
    for line in _rows(state, "lines"):
        if line.get("line_id") == target:
            details = dict(line)
            details["entity_type"] = "line"
            return details

    # Device
    for device in _rows(state, "devices"):
        if device.get("device_id") == target:
            details = dict(device)
            details["entity_type"] = "device"
            return details

    # Bill
    for bill in _rows(state, "bills"):
        if bill.get("bill_id") == target:
            details = dict(bill)
            details["entity_type"] = "bill"
            details["line_items"] = [
                dict(li)
                for li in _rows(state, "bill_line_items")
                if li.get("bill_id") == target
            ]
            return details

    # Plan
    for plan in _rows(state, "plans"):
        if plan.get("plan_id") == target:
            details = dict(plan)
            details["entity_type"] = "plan"
            return details

    raise ValueError(
        "No Customer, Line, Device, Bill, or Plan found with ID '{}'.".format(target)
    )

# confidence=high  # note: Assumed app must exist and be installed. Permission matching/creation is case-insensitive and stored
def grant_app_permission(state, app_name, permission):
    if not app_name or not isinstance(app_name, str):
        raise ValueError("app_name is required")
    if not permission or not isinstance(permission, str):
        raise ValueError("permission is required")

    app_key = app_name.strip().lower()
    perm_key = permission.strip().lower()

    app = None
    for row in _rows(state, "apps"):
        if str(row.get("app_name", "")).strip().lower() == app_key:
            app = row
            break
    if app is None:
        raise ValueError(f"App '{app_name}' is not found on the device.")
    if not app.get("installed", False):
        raise ValueError(f"App '{app_name}' is not installed on the device.")

    perms = _rows(state, "app_permissions")
    record = None
    for row in perms:
        if (str(row.get("app_name", "")).strip().lower() == app_key
                and str(row.get("permission", "")).strip().lower() == perm_key):
            record = row
            break

    if record is None:
        record = {
            "app_permission_id": f"{app_key}_{perm_key}",
            "app_name": app.get("app_name", app_name),
            "permission": perm_key,
            "granted": True,
        }
        perms.append(record)
        return f"Permission '{perm_key}' granted to app '{record['app_name']}'."

    if record.get("granted", False):
        return f"Permission '{perm_key}' was already granted to app '{record.get('app_name', app_name)}'."

    record["granted"] = True
    return f"Permission '{perm_key}' granted to app '{record.get('app_name', app_name)}'."

# confidence=high  # note: Assumed the payment request singleton holds the bill being paid; a payment can only be made when a r
def make_payment(state):
    """Makes a payment for the bill that the agent has sent a payment request for."""
    request = state.get("payment_request") or {}

    if not request or not request.get("sent"):
        raise ValueError("No payment request has been sent.")

    bill_id = request.get("bill_id")
    if not bill_id:
        raise ValueError("No payment request has been sent.")

    status = (request.get("status") or "").strip().lower()
    if status in ("paid", "completed"):
        raise ValueError("The payment request has already been paid.")
    if status in ("cancelled", "canceled", "rejected", "declined", "expired"):
        raise ValueError("The payment request is no longer valid: " + str(request.get("status")))

    bill = _find(state, "bills", "bill_id", bill_id)

    bill_status = (bill.get("status") or "").strip().lower()
    if bill_status == "paid":
        raise ValueError("Bill " + str(bill_id) + " has already been paid.")
    if bill_status.replace("_", " ") != "awaiting payment":
        raise ValueError(
            "Bill " + str(bill_id) + " is not awaiting payment (current status: "
            + str(bill.get("status")) + ")."
        )

    amount = bill.get("total_amount_due", 0)

    bill["status"] = "Paid"
    request["status"] = "Paid"
    request["sent"] = False
    request["amount_due"] = 0

    return (
        "Payment of $" + format(float(amount), ".2f") + " for bill "
        + str(bill_id) + " completed. The bill status is now Paid."
    )

# confidence=medium  # note: Assumed a reboot clears phone.pending_reboot and that pending APN/MMSC changes only take effect afte
def reboot_device(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("No phone found in state")

    was_pending = bool(phone.get("pending_reboot", False))

    # The reboot completes; any settings waiting on a restart are now applied.
    phone["pending_reboot"] = False

    if was_pending:
        apn_ok = str(phone.get("apn_settings_status", "")).strip().lower() in (
            "correct",
            "ok",
            "valid",
            "default",
        )
        mmsc_ok = bool(str(phone.get("mmsc_url", "")).strip())
        service_ok = (
            not phone.get("airplane_mode", False)
            and str(phone.get("signal_strength", "")).strip().lower() not in ("", "none")
            and str(phone.get("sim_status", "")).strip().lower() == "active"
        )
        data_ok = bool(phone.get("mobile_data_enabled", False))
        if apn_ok and mmsc_ok and service_ok and data_ok:
            phone["can_send_mms"] = True

    return (
        "Device rebooted successfully. Pending settings changes have been applied."
        if was_pending
        else "Device rebooted successfully."
    )

# confidence=high  # note: Schema has no explicit 'current/open bill' marker, so the charge goes to the customer's Draft bill i
def refuel_data(state, customer_id, line_id, gb_amount):
    # Validate customer exists
    customer = _find(state, "customers", "customer_id", customer_id)

    # Validate line exists
    line = _find(state, "lines", "line_id", line_id)

    # Customer must own the line
    if line.get("customer_id") != customer_id:
        raise ValueError(
            "Line {} does not belong to customer {}.".format(line_id, customer_id)
        )

    # Line must be active
    if str(line.get("status", "")).strip().lower() != "active":
        raise ValueError(
            "Line {} is not Active (current status: {}).".format(
                line_id, line.get("status")
            )
        )

    # Validate requested amount
    try:
        gb = float(gb_amount)
    except (TypeError, ValueError):
        raise ValueError("gb_amount must be a number.")
    if gb <= 0:
        raise ValueError("gb_amount must be greater than 0.")
    if gb > 2:
        raise ValueError("The maximum amount of data that can be refueled is 2GB.")

    # Find the plan for pricing
    plan = _find(state, "plans", "plan_id", line.get("plan_id"))
    price_per_gb = float(plan.get("data_refueling_price_per_gb") or 0)
    charge = round(gb * price_per_gb, 2)

    # Apply the refueled data to the line
    line["data_refueling_gb"] = round(float(line.get("data_refueling_gb") or 0) + gb, 2)

    # Charge the customer: attach the charge to a bill
    bills = [b for b in _rows(state, "bills") if b.get("customer_id") == customer_id]
    if not bills:
        raise ValueError("No bill found for customer {}.".format(customer_id))

    target_bill = None
    for b in bills:
        if str(b.get("status", "")).strip().lower() == "draft":
            target_bill = b
            break
    if target_bill is None:
        target_bill = sorted(bills, key=lambda b: str(b.get("issue_date") or ""))[-1]

    line_items = _rows(state, "bill_line_items")
    existing_ids = {str(li.get("line_item_id")) for li in line_items}
    n = len(line_items) + 1
    new_id = "BLI{:04d}".format(n)
    while new_id in existing_ids:
        n += 1
        new_id = "BLI{:04d}".format(n)

    line_items.append(
        {
            "line_item_id": new_id,
            "bill_id": target_bill.get("bill_id"),
            "description": "Data refueling {}GB for line {}".format(gb, line_id),
            "amount": charge,
            "item_type": "charge",
        }
    )
    target_bill["total_amount_due"] = round(
        float(target_bill.get("total_amount_due") or 0) + charge, 2
    )

    return (
        "Refueled {}GB on line {} ({}). Charge of ${:.2f} added to bill {}.".format(
            gb,
            line_id,
            line.get("phone_number"),
            charge,
            target_bill.get("bill_id"),
        )
    )

# confidence=high  # note: Assumed reseating recovers a 'Missing' SIM to 'Active', leaves a Locked SIM locked, and leaves an al
def reseat_sim_card(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("No phone found in state")

    current = str(phone.get("sim_status", "") or "")
    normalized = current.strip().lower()

    if normalized in ("missing", "not inserted", "none", ""):
        phone["sim_status"] = "Active"
        return (
            "SIM card removed and reinserted. The SIM is now detected and its status is Active."
        )

    if "lock" in normalized or "pin" in normalized or "puk" in normalized:
        return (
            "SIM card removed and reinserted, but the SIM is still Locked ("
            + current
            + "). Reseating cannot unlock a SIM."
        )

    return (
        "SIM card removed and reinserted. SIM status is " + current + "."
    )

