# confidence=medium  # note: Assumed the line must belong to the given customer. Enforced the policy rule that a suspension canno
def resume_line(state, customer_id, line_id):
    from datetime import datetime

    # Validate customer exists
    _find(state, "customers", "customer_id", customer_id)

    line = _find(state, "lines", "line_id", line_id)

    if line.get("customer_id") != customer_id:
        raise ValueError(
            f"Line {line_id} does not belong to customer {customer_id}."
        )

    status = (line.get("status") or "").strip().lower()
    if status not in ("suspended", "pending activation", "pending_activation"):
        raise ValueError(
            f"Line {line_id} has status '{line.get('status')}'. "
            "Only lines with status 'Suspended' or 'Pending Activation' can be resumed."
        )

    # Policy: a suspension cannot be lifted when the contract end date is in the past.
    contract_end = line.get("contract_end_date")
    if contract_end:
        parsed = None
        for fmt in ("%Y-%m-%d", "%Y-%m-%dT%H:%M:%S", "%Y/%m/%d", "%m/%d/%Y"):
            try:
                parsed = datetime.strptime(str(contract_end)[:19], fmt)
                break
            except ValueError:
                continue
        if parsed is not None:
            # DATE comparison, not datetime. `str(contract_end)[:19]` parses a bare
            # date to midnight, so comparing instants made a contract ending TODAY
            # already expired from 00:00 — while `suspension_liftable`, the guard whose
            # only job is to say whether this call is permitted, compared dates and said
            # it was fine. A guard that is true where its tool raises is worse than none.
            # The policy says "the contract end date is in the past"; a contract ending
            # today has not ended, and time of day is not on the field.
            now = _now(state)
            if parsed.date() < now.date():
                raise ValueError(
                    f"Line {line_id} cannot be resumed because its contract end date "
                    f"({contract_end}) is in the past."
                )

    line["status"] = "Active"
    line["suspension_start_date"] = None

    return f"Line {line_id} has been resumed and is now Active."

# confidence=medium  # note: Assumed a speed test reports 'no connection' when airplane mode is on, or when there is no signal / 
def run_speed_test(state):
    """Measures the current internet connection speed (download speed).

    Read-only diagnostic tool. Reports the phone's download speed and
    connection quality, plus what activities the connection can support.
    """
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("Phone state is not available")

    airplane_mode = bool(phone.get("airplane_mode", False))
    mobile_data_enabled = bool(phone.get("mobile_data_enabled", False))
    signal_strength = (phone.get("signal_strength") or "").strip().lower()
    wifi_enabled = bool(phone.get("wifi_enabled", False))
    wifi_ssid = phone.get("wifi_ssid") or ""
    wifi_connected = wifi_enabled and bool(wifi_ssid)

    cellular_data_available = (
        not airplane_mode
        and mobile_data_enabled
        and signal_strength not in ("", "none", "no signal")
    )

    if airplane_mode:
        connection_available = False
    else:
        connection_available = cellular_data_available or wifi_connected

    if not connection_available:
        return {
            "connected": False,
            "download_speed": "no connection",
            "connection_quality": "no connection",
            "supported_activities": [],
            "message": "No connection. The speed test could not reach the internet.",
        }

    download_speed = (phone.get("download_speed") or "unknown").strip().lower()
    connection_quality = phone.get("connection_quality") or "unknown"

    if download_speed in ("", "none", "no connection"):
        return {
            "connected": False,
            "download_speed": "no connection",
            "connection_quality": "no connection",
            "supported_activities": [],
            "message": "No connection. The speed test could not reach the internet.",
        }

    activities_by_speed = {
        "excellent": [
            "HD/4K video streaming",
            "video calls",
            "large downloads",
            "online gaming",
            "web browsing",
            "messaging (including MMS)",
        ],
        "good": [
            "HD video streaming",
            "video calls",
            "web browsing",
            "messaging (including MMS)",
        ],
        "fair": [
            "standard definition video streaming",
            "web browsing",
            "messaging (including MMS)",
        ],
        "poor": ["web browsing (slow)", "messaging (including MMS)"],
        "very poor": ["basic messaging"],
        "unknown": [],
    }

    supported_activities = activities_by_speed.get(download_speed, [])

    return {
        "connected": True,
        "download_speed": download_speed,
        "connection_quality": connection_quality,
        "connection_source": "wifi" if (wifi_connected and not cellular_data_available) else "cellular",
        "network_type": phone.get("network_type"),
        "supported_activities": supported_activities,
        "message": "Download speed is {0}.".format(download_speed),
    }

# confidence=high  # note: Assumed bill status string 'Awaiting Payment' (policy wording) with normalized comparison tolerating
def send_payment_request(state, customer_id, bill_id):
    def _norm(value):
        return str(value or "").strip().lower().replace("_", " ")

    customer = _find(state, "customers", "customer_id", customer_id)
    bill = _find(state, "bills", "bill_id", bill_id)

    if bill.get("customer_id") != customer_id:
        raise ValueError(
            "Bill " + str(bill_id) + " does not belong to customer " + str(customer_id)
        )

    for other in _rows(state, "bills"):
        if other.get("customer_id") != customer_id:
            continue
        if other.get("bill_id") == bill_id:
            continue
        if _norm(other.get("status")) == "awaiting payment":
            raise ValueError(
                "Customer "
                + str(customer_id)
                + " already has a bill awaiting payment: "
                + str(other.get("bill_id"))
            )

    bill["status"] = "Awaiting Payment"

    request = state.get("payment_request")
    if not isinstance(request, dict):
        request = {}
        state["payment_request"] = request
    request["sent"] = True
    request["customer_id"] = customer_id
    request["bill_id"] = bill_id
    request["amount_due"] = bill.get("total_amount_due", 0)
    request["status"] = "Pending"

    return (
        "Payment request for bill "
        + str(bill_id)
        + " (amount due $"
        + str(bill.get("total_amount_due", 0))
        + ") sent to "
        + str(customer.get("full_name", customer_id))
        + ". Bill status is now Awaiting Payment."
    )

# confidence=medium  # note: The tool takes a single opaque string, so it is stored in the closest existing field (phone.apn_name
def set_apn_settings(state, apn_settings):
    """Sets the APN settings for the phone.

    Precondition: apn_settings must be a non-empty string.
    Postcondition: the phone's APN name is set to the provided value and the
    device is flagged as needing a reboot for the change to take effect.
    """
    if apn_settings is None or not isinstance(apn_settings, str) or not apn_settings.strip():
        raise ValueError("apn_settings must be a non-empty string")

    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("No phone found in state")

    value = apn_settings.strip()
    phone["apn_name"] = value
    phone["pending_reboot"] = True

    return (
        "APN settings set to '" + value + "'. "
        "A device reboot is required for the change to take effect."
    )

# confidence=medium  # note: Assumed a fixed list of valid network mode strings (the policy only names '4g_5g_preferred' and '4g_
def set_network_mode_preference(state, mode):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("No phone found in state")

    if mode is None or not isinstance(mode, str) or not mode.strip():
        raise ValueError("mode is required")

    normalized = mode.strip().lower().replace("-", "_").replace(" ", "_")

    # Accepted network mode preferences and the network technology they yield
    valid_modes = {
        "5g_only": "5G",
        "5g_preferred": "5G",
        "4g_5g_preferred": "5G",
        "5g_4g_preferred": "5G",
        "4g_only": "4G",
        "lte_only": "4G",
        "4g_preferred": "4G",
        "lte_preferred": "4G",
        "3g_only": "3G",
        "3g_preferred": "3G",
        "2g_only": "2G",
        "2g_preferred": "2G",
    }

    if normalized not in valid_modes:
        raise ValueError(
            "Invalid network mode preference: "
            + str(mode)
            + ". Valid modes are: "
            + ", ".join(sorted(valid_modes.keys()))
        )

    phone["network_mode_preference"] = normalized

    # Reflect the new preference in the currently reported network technology,
    # but only when the phone is actually able to connect to a network.
    if not phone.get("airplane_mode") and str(phone.get("signal_strength", "")).lower() not in (
        "none",
        "",
    ):
        phone["network_type"] = valid_modes[normalized]

    return (
        "Network mode preference set to '"
        + normalized
        + "'. Current network type: "
        + str(phone.get("network_type"))
        + "."
    )

# confidence=high  # note: Used the policy's current time (2025-02-25 EST) as the suspension start date rather than a runtime c
def suspend_line(state, customer_id, line_id, reason):
    # Verify the customer exists
    _find(state, "customers", "customer_id", customer_id)

    # Verify the line exists
    line = _find(state, "lines", "line_id", line_id)

    # The line must belong to the given customer
    if line.get("customer_id") != customer_id:
        raise ValueError(
            "Line {} does not belong to customer {}.".format(line_id, customer_id)
        )

    # Check: line status must be Active
    if str(line.get("status", "")).strip().lower() != "active":
        raise ValueError(
            "Line {} cannot be suspended because its status is '{}' (must be Active).".format(
                line_id, line.get("status")
            )
        )

    # Logic: suspend the line and record the suspension start date
    suspension_start_date = _now(state).date().isoformat()
    line["status"] = "Suspended"
    line["suspension_start_date"] = suspension_start_date
    line["suspension_reason"] = reason

    return (
        "Line {} ({}) has been suspended as of {}. Reason: {}.".format(
            line_id, line.get("phone_number"), suspension_start_date, reason
        )
    )

# confidence=medium  # note: No parameters, so the tool flips the current value. Turning airplane mode ON forces the derived radi
def toggle_airplane_mode(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("No phone found in state.")

    current = bool(phone.get("airplane_mode", False))
    new_value = not current
    phone["airplane_mode"] = new_value

    if new_value:
        # Airplane mode ON: all wireless radios are disconnected.
        phone["signal_strength"] = "none"
        phone["network_type"] = "none"
        phone["wifi_enabled"] = False
        phone["wifi_ssid"] = ""
        phone["wifi_signal_strength"] = "none"
        phone["download_speed"] = "unknown"
        phone["connection_quality"] = "no connection"
        phone["can_send_mms"] = False
    else:
        # Airplane mode OFF: cellular radio comes back if the SIM is usable.
        sim_status = str(phone.get("sim_status", "")).strip().lower()
        if sim_status == "active":
            if str(phone.get("signal_strength", "")).strip().lower() in ("", "none"):
                phone["signal_strength"] = "good"
            preference = str(phone.get("network_mode_preference", "")).strip().lower()
            if str(phone.get("network_type", "")).strip().lower() in ("", "none"):
                if "2g" in preference:
                    phone["network_type"] = "2G"
                elif "3g" in preference:
                    phone["network_type"] = "3G"
                elif "5g" in preference:
                    phone["network_type"] = "5G"
                else:
                    phone["network_type"] = "4G"

    return "Airplane mode is now " + ("ON" if new_value else "OFF") + "."

# confidence=high  # note: No parameters, so the tool simply flips the current mobile_data_enabled value. No extra precondition
def toggle_data(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("Phone state is not available.")

    current = bool(phone.get("mobile_data_enabled", False))
    new_value = not current
    phone["mobile_data_enabled"] = new_value

    return "Mobile data is now ON." if new_value else "Mobile data is now OFF."

# confidence=high  # note: No preconditions specified for this toggle; it simply flips phone.data_saver_enabled and reports the
def toggle_data_saver_mode(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("Phone state is not available.")

    current = bool(phone.get("data_saver_enabled", False))
    new_status = not current
    phone["data_saver_enabled"] = new_status

    return "Data Saver mode is now ON" if new_status else "Data Saver mode is now OFF"

# confidence=high  # note: Tool takes no parameters, so it simply flips the device-level phone.roaming_enabled flag (not the li
def toggle_roaming(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("Phone state is not available.")
    current = bool(phone.get("roaming_enabled", False))
    phone["roaming_enabled"] = not current
    return "Data Roaming is now ON" if phone["roaming_enabled"] else "Data Roaming is now OFF"

# confidence=high  # note: Assumed turning Wi-Fi off clears the connected SSID and sets signal strength to 'none'; turning it o
def toggle_wifi(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("Phone state is not available.")

    new_status = not bool(phone.get("wifi_enabled", False))
    phone["wifi_enabled"] = new_status

    if not new_status:
        # Turning Wi-Fi off disconnects from any network
        phone["wifi_ssid"] = ""
        phone["wifi_signal_strength"] = "none"
        return "Wi-Fi is now OFF. The phone is disconnected from any wireless network."

    ssid = phone.get("wifi_ssid") or ""
    if ssid:
        return (
            "Wi-Fi is now ON and connected to "
            + str(ssid)
            + " (signal: "
            + str(phone.get("wifi_signal_strength") or "unknown")
            + ")."
        )
    return "Wi-Fi is now ON. Not connected to any network."

# confidence=high  # note: No parameters, so the tool simply flips the current Wi-Fi Calling state and returns the new status a
def toggle_wifi_calling(state):
    phone = state.get("phone")
    if not isinstance(phone, dict):
        raise ValueError("Phone state is not available.")
    current = bool(phone.get("wifi_calling_enabled", False))
    new_status = not current
    phone["wifi_calling_enabled"] = new_status
    return "Wi-Fi Calling is now ON" if new_status else "Wi-Fi Calling is now OFF"

# confidence=high  # note: Assumed a repeated transfer is a precondition failure, and that a blank summary is invalid since the
def transfer_to_human_agents(state, summary):
    if summary is None or not isinstance(summary, str) or not summary.strip():
        raise ValueError("A non-empty summary of the user's issue is required to transfer to a human agent.")

    transfer = state.get("transfer")
    if not isinstance(transfer, dict):
        raise ValueError("Transfer state is unavailable.")

    if transfer.get("transferred_to_human"):
        raise ValueError("The user has already been transferred to a human agent.")

    transfer["transferred_to_human"] = True
    transfer["summary"] = summary.strip()

    return "Transfer successful"

# ---- derived state: recomputed after every call, like a database trigger
def derive(state):
    """Recompute every user-perceived observable from the base (tool-written) fields.
    Pure function of the base state -> idempotent."""
    def _s(v):
        return str(v).strip().lower() if v is not None else ""

    phone = state.get("phone")
    if not isinstance(phone, dict):
        return state

    lines = state.get("lines") or []
    # The handset in `phone` is assumed to belong to the first line on file.
    line = lines[0] if lines else None

    plan = None
    if line is not None:
        for p in (state.get("plans") or []):
            if p.get("plan_id") == line.get("plan_id"):
                plan = p
                break

    pending = bool(phone.get("pending_reboot"))
    airplane = bool(phone.get("airplane_mode"))
    sim_ok = _s(phone.get("sim_status")) in ("active", "ok", "ready")
    apn_ok = (_s(phone.get("apn_settings_status")) in ("correct", "ok", "valid", "default")
              and not pending)
    line_ok = True
    if line is not None:
        line_ok = _s(line.get("status")) == "active"

    # ---- cellular service ----
    has_service = (not airplane) and sim_ok and apn_ok and line_ok

    mode = _s(phone.get("network_mode_preference"))
    if not has_service:
        network_type = "none"
    elif "5g" in mode:
        network_type = "5G"
    elif "4g" in mode:
        network_type = "4G"
    elif "3g" in mode:
        network_type = "3G"
    elif "2g" in mode:
        network_type = "2G"
    else:
        network_type = "4G"

    if not has_service:
        signal = "none"
    elif network_type in ("2G", "3G"):
        signal = "fair"
    else:
        signal = "excellent"

    # ---- mobile data ----
    over_limit = False
    if line is not None and plan is not None:
        try:
            allowance = float(plan.get("data_limit_gb") or 0) + float(line.get("data_refueling_gb") or 0)
            used = float(line.get("data_usage_gb") or 0)
            over_limit = allowance > 0 and used >= allowance
        except (TypeError, ValueError):
            over_limit = False

    order = ["unknown", "very poor", "poor", "fair", "good", "excellent"]
    data_up = has_service and bool(phone.get("mobile_data_enabled")) and not over_limit
    if not data_up:
        speed = "unknown"
    else:
        base = {"5G": "excellent", "4G": "good", "3G": "poor", "2G": "very poor"}.get(network_type, "good")
        idx = order.index(base)
        if phone.get("data_saver_enabled"):
            idx -= 1
        if (phone.get("vpn_active") and phone.get("vpn_connected")
                and _s(phone.get("vpn_performance_level")) in ("poor", "very poor", "bad", "degraded")):
            idx -= 2
        if idx < 1:
            idx = 1
        speed = order[idx]

    quality = {"unknown": "no connection", "very poor": "poor", "poor": "poor",
               "fair": "fair", "good": "good", "excellent": "excellent"}[speed]

    # ---- MMS ----
    mmsc = _s(phone.get("mmsc_url"))
    mmsc_ok = (mmsc not in ("", "none", "not set", "unset", "null", "n/a")) and not pending

    perm_rows = [ap for ap in (state.get("app_permissions") or [])
                 if _s(ap.get("app_name")) == "messaging"]
    msg_app_known = bool(perm_rows) or any(
        _s(a.get("app_name")) == "messaging" for a in (state.get("apps") or []))
    if msg_app_known:
        granted = {}
        for ap in perm_rows:
            granted[_s(ap.get("permission"))] = bool(ap.get("granted"))
        msg_perms_ok = bool(granted.get("storage")) and bool(granted.get("sms"))
    else:
        msg_perms_ok = True

    can_mms = (has_service and speed != "unknown" and mmsc_ok
               and network_type != "2G"
               and not bool(phone.get("wifi_calling_enabled"))
               and msg_perms_ok)

    phone["signal_strength"] = signal
    phone["network_type"] = network_type
    phone["download_speed"] = speed
    phone["connection_quality"] = quality
    phone["can_send_mms"] = bool(can_mms)
    return state

# The phone shows a usable cellular signal (calls/texts work).
def has_cellular_service(state):
    phone = state.get("phone") or {}
    sig = str(phone.get("signal_strength") or "").strip().lower()
    net = str(phone.get("network_type") or "").strip().lower()
    return sig not in ("", "none", "no signal") and net not in ("", "none")

# The SIM card is recognized and active (not missing, not PIN/PUK locked).
def sim_card_healthy(state):
    phone = state.get("phone") or {}
    return str(phone.get("sim_status") or "").strip().lower() in ("active", "ok", "ready")

# APN name and MMSC URL are correct AND the reboot needed to apply them has been done.
def apn_settings_healthy(state):
    phone = state.get("phone") or {}
    status = str(phone.get("apn_settings_status") or "").strip().lower()
    mmsc = str(phone.get("mmsc_url") or "").strip().lower()
    return (status in ("correct", "ok", "valid", "default")
            and mmsc not in ("", "none", "not set", "unset", "null", "n/a")
            and not bool(phone.get("pending_reboot")))

# The line has an actual internet connection over mobile data (any speed).
def mobile_data_working(state):
    phone = state.get("phone") or {}
    speed = str(phone.get("download_speed") or "").strip().lower()
    return speed not in ("", "unknown", "none", "no connection")

# Mobile data speed is 'excellent' — i.e. not slowed by data saver, VPN or a 2G/3G preference.
def mobile_data_fast(state):
    phone = state.get("phone") or {}
    return str(phone.get("download_speed") or "").strip().lower() == "excellent"

# Picture/video messages can be sent (service + data + MMSC + non-2G + Wi-Fi calling off + app permissions).
def mms_working(state):
    phone = state.get("phone") or {}
    return bool(phone.get("can_send_mms"))

# The line still has data left this cycle (plan limit plus refueled GB not exhausted).
def data_allowance_available(state):
    lines = state.get("lines") or []
    if not lines:
        return False
    line = lines[0]
    plan = None
    for p in (state.get("plans") or []):
        if p.get("plan_id") == line.get("plan_id"):
            plan = p
            break
    if plan is None:
        return False
    try:
        allowance = float(plan.get("data_limit_gb") or 0) + float(line.get("data_refueling_gb") or 0)
        used = float(line.get("data_usage_gb") or 0)
    except (TypeError, ValueError):
        return False
    return allowance > 0 and used < allowance

# The line is active with no suspension in effect.
def line_active(state):
    lines = state.get("lines") or []
    if not lines:
        return False
    line = lines[0]
    status = str(line.get("status") or "").strip().lower()
    susp = str(line.get("suspension_start_date") or "").strip().lower()
    return status == "active" and susp in ("", "none", "null", "n/a")

# The customer has no overdue, awaiting-payment or disputed bills left.
def no_outstanding_bills(state):
    lines = state.get("lines") or []
    cust = lines[0].get("customer_id") if lines else None
    bills = [b for b in (state.get("bills") or [])
             if cust is None or b.get("customer_id") == cust]
    for b in bills:
        if str(b.get("status") or "").strip().lower() in ("overdue", "awaiting payment", "disputed"):
            return False
    return True

# A payment request was sent and its bill is now confirmed PAID.
def payment_request_settled(state):
    pr = state.get("payment_request") or {}
    if not pr.get("sent"):
        return False
    bill_id = pr.get("bill_id")
    for b in (state.get("bills") or []):
        if b.get("bill_id") == bill_id:
            return str(b.get("status") or "").strip().lower() == "paid"
    return False

# The suspended line may be resumed by the agent: all bills settled and contract not expired.
def suspension_liftable(state):
    import datetime
    NOW = _now(state).date()
    lines = state.get("lines") or []
    if not lines:
        return False
    line = lines[0]
    if str(line.get("status") or "").strip().lower() != "suspended":
        return False
    cust = line.get("customer_id")
    for b in (state.get("bills") or []):
        if b.get("customer_id") == cust and str(b.get("status") or "").strip().lower() in ("overdue", "awaiting payment"):
            return False
    end = str(line.get("contract_end_date") or "").strip()
    try:
        end_d = datetime.date(*[int(x) for x in end.split("-")[:3]])
    except Exception:
        return False
    return end_d >= NOW

# Both the line and the handset have data roaming enabled, so data works outside the home network.
def roaming_ready(state):
    phone = state.get("phone") or {}
    lines = state.get("lines") or []
    if not lines:
        return False
    line = lines[0]
    return (bool(line.get("roaming_enabled")) and bool(phone.get("roaming_enabled"))
            and not bool(phone.get("airplane_mode")))

# The messaging app holds both the storage and sms permissions required for MMS.
def messaging_app_permissions_ready(state):
    granted = {}
    for ap in (state.get("app_permissions") or []):
        if str(ap.get("app_name") or "").strip().lower() == "messaging":
            granted[str(ap.get("permission") or "").strip().lower()] = bool(ap.get("granted"))
    if not granted:
        return False
    return bool(granted.get("storage")) and bool(granted.get("sms"))

# The case was handed off to a human agent (terminal outcome when nothing else resolves it).
def escalated_to_human(state):
    tr = state.get("transfer") or {}
    return bool(tr.get("transferred_to_human"))

